            "id": "quarterly-volatility",
            "statement": "직전 4개 분기 중 2025-11-01 마감 분기는 영업이익률 -3.7%(영업손실 734.4만달러)를 기록하는 등 분기별 손익 변동성이 크고, ADR(일중 변동성) 4.58%로 단기 변동성도 높아 상승 추세의 되돌림 리스크가 상존한다.",
